mapper.select:
SELECT T.*, CASE WHEN sysProjectFunctionDefaultLabel is not null THEN 1 ELSE 0 END sysProjectFunctionDefault FROM (
SELECT sp.*,
       (SELECT group_concat(spd.sys_project_default_type)
        FROM sys_project_default spd
        WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultLabel,
       (SELECT group_concat(spd.sys_project_default_type)
        FROM sys_project_default spd
        WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultIds
FROM sys_project sp



            AND sys_project_id = #{request.sysProjectId}


            AND sys_project_name LIKE CONCAT('%', #{request.sysProjectName}, '%')


            AND sys_project_group = #{request.sysProjectGroup}


            AND sys_project_status = #{request.sysProjectStatus}


            AND sys_project_delete = #{request.sysProjectDelete}



            AND sys_project_vender = #{request.sysProjectVender}



            AND FIND_IN_SET(#{request.sysProjectFunction}, sys_project_function)



) T
ORDER BY sysProjectFunctionDefault desc, sys_project_sort
